export const AppShell = ({ children }: { children: React.ReactNode }) => {
  const contentRef = useRef<HTMLDivElement>(null)
  const [contentWidth, setContentWidth] = useState<number | null>(null)

  useEffect(() => {
    const el = contentRef.current
    if (!el) return
    const measure = () => setContentWidth(Math.round(el.getBoundingClientRect().width))
    measure()
    const ro = new ResizeObserver(measure)
    ro.observe(el)
    window.addEventListener("resize", measure)
    return () => {
      ro.disconnect()
      window.removeEventListener("resize", measure)
    }
  }, [])

  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset className="overflow-hidden flex flex-col">
        <header className="flex h-12 shrink-0 items-center gap-2 border-b border-border px-4 z-20 font-mono">
          <SidebarTrigger className="-ml-1" />
          <Separator orientation="vertical" className="mr-2 data-vertical:h-4 data-vertical:self-auto" />
          <BreadcrumbNav />
          <div className="ml-auto pr-2">
            <PlttLogo />
          </div>
        </header>

        {/* Horizontal-scroll wrapper: when the window is narrower than
            MIN_CONTENT_WIDTH the content keeps that width and scrolls instead of
            cramming. */}
        <div className="flex-1 min-h-0" style={{ overflowX: "auto", overflowY: "hidden" }}>
          <div
            ref={contentRef}
            className="flex flex-col overflow-hidden"
            style={{ minWidth: MIN_CONTENT_WIDTH, width: "100%", height: "100%" }}
          >
            <ContentWidthProvider width={contentWidth}>{children}</ContentWidthProvider>
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}
